#include <iostream>




#include <cmath>




#include <iomanip>




using namespace std;




struct Point{long double x,y;};




long double length(Point a,Point b){return hypotl(a.x-b.x,a.y-b.y);}




int main(){Point a,b,c;cin>>a.x>>a.y>>b.x>>b.y>>c.x>>c.y;




long double cross=(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);




if(fabsl(cross)<1e-15L){cout<<"-1\n";return 0;}




long double perimeter=length(a,b)+length(b,c)+length(c,a);




long double area=fabsl(cross)/2;




cout<<fixed<<setprecision(1)<<perimeter<<' '<<setprecision(2)<<area<<'\n';}
